function journal_visibility_refresh(PDO $db,array $plan,array $auth=[]): array {
    $ids=['tracks'=>[],'albums'=>[],'playlists'=>[]];foreach($plan['ops']as $op)if(isset($ids[$op['table']])&&(($op['after']['visibility']??null)==='public'||($op['after']['deleted']??null)===0))$ids[$op['table']][]=$op['id'];$auditTracks=isset($auth['token'])?array_values(array_filter($plan['ops'],fn($op)=>$op['table']==='tracks')):[];if(!array_filter($ids)&&!$auditTracks)return $plan;
    $plan['guards']??=array_values(array_map(fn($op)=>['table'=>$op['table'],'id'=>$op['id'],'rev'=>$op['before']['rev']],array_filter($plan['ops'],fn($op)=>$op['before']!==null)));$plan['counts']??=[];$artists=[];$items=[];$auditAlbums=[];foreach(array_chunk(array_column($auditTracks,'id'),200)as $group)foreach(query_all($db,'SELECT a.id,a.rev FROM albums a JOIN tracks t ON t.album_id=a.id WHERE t.id IN('.implode(',',array_fill(0,count($group),'?')).')',$group)as $row)$auditAlbums[$row['id']]=$row;$afterIds=[];foreach($auditTracks as $op)if(isset($op['after']['album_id']))$afterIds[]=$op['after']['album_id'];foreach(array_chunk(array_values(array_unique($afterIds)),200)as $group)foreach(query_all($db,'SELECT id,rev FROM albums WHERE id IN('.implode(',',array_fill(0,count($group),'?')).')',$group)as $row)$auditAlbums[$row['id']]=$row;
    foreach(['tracks','albums']as $table)foreach(array_chunk($ids[$table],200)as $group)foreach(query_all($db,'SELECT DISTINCT ar.id,ar.rev FROM artists ar JOIN '.$table.' t ON t.artist_id=ar.id WHERE ar.deleted=0 AND t.id IN('.implode(',',array_fill(0,count($group),'?')).')',$group)as $row)$artists[$row['id']]=$row;
    foreach(['tracks'=>'track_id','playlists'=>'playlist_id']as $table=>$column)foreach(array_chunk($ids[$table],200)as $group)foreach(query_all($db,'SELECT id,rev,playlist_id,track_id FROM playlist_items WHERE deleted=0 AND '.$column.' IN('.implode(',',array_fill(0,count($group),'?')).')',$group)as $row)$items[$row['id']]=$row;
    $seen=[];foreach($plan['ops']as $op)$seen[$op['table'].':'.$op['id']]=true;foreach(['artists'=>$artists,'playlist_items'=>$items,'albums'=>$auditAlbums]as $table=>$rows)foreach($rows as $row){if(isset($seen[$table.':'.$row['id']]))continue;$plan['ops'][]=['table'=>$table,'id'=>$row['id'],'before'=>['id'=>$row['id'],'rev'=>$row['rev']],'after'=>['id'=>$row['id'],'rev'=>$row['rev']],'system'=>true,'audit'=>$table==='albums'];$plan['guards'][]=['table'=>$table,'id'=>$row['id'],'rev'=>$row['rev'],'system'=>true];}
    foreach(['tracks'=>'track_id','playlists'=>'playlist_id']as $table=>$column)foreach($ids[$table]as $id){if(array_filter($plan['counts'],fn($guard)=>$guard['table']==='playlist_items'&&$guard['column']===$column&&$guard['id']===$id))continue;$plan['counts'][]=['table'=>'playlist_items','column'=>$column,'id'=>$id,'count'=>count(array_filter($items,fn($item)=>$item[$column]===$id))];}return $plan;
}

function journal_row_dependencies(string $table,array $row): array {
    if((int)$row['deleted']===1)return [];$fields=$table==='tracks'?[['album_id','albums'],['artist_id','artists']]:($table==='albums'?[['artist_id','artists']]:($table==='playlist_items'?[['playlist_id','playlists'],['track_id','tracks']]:[]));$rows=[];foreach($fields as [$field,$target])if(isset($row[$field])&&is_string($row[$field]))$rows[]=['table'=>$target,'id'=>$row[$field]];return $rows;
}
